import{_ as e,o as h,c as i,a2 as t}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Learning Experience là gì","description":"","frontmatter":{},"headers":[],"relativePath":"learning/learning-experience.md","filePath":"learning/learning-experience.md"}'),g={name:"learning/learning-experience.md"};function c(r,n,a,o,l,u){return h(),i("div",null,[...n[0]||(n[0]=[t('<h1 id="learning-experience-la-gi" tabindex="-1">Learning Experience là gì <a class="header-anchor" href="#learning-experience-la-gi" aria-label="Permalink to &quot;Learning Experience là gì&quot;">​</a></h1><p>Trên trang này# Learning Experience là gì <a href="#learning-experience-la-gi">​</a> Một Learning Experience là hoạt động được thiết kế với đúng một mục đích: <strong>làm learner giỏi hơn so với lúc bắt đầu</strong>. Nghe hiển nhiên, nhưng phần lớn thời gian học ở nhà lại không thoả định nghĩa này. Chép bài không làm learner giỏi hơn — nó chỉ chuyển chữ từ chỗ này sang chỗ khác. Làm đề thi thử cũng không: đề thi thử được thiết kế để <em>đo</em>, không phải để dạy. Cả hai đều là hoạt động hợp lệ, nhưng chúng không phải Learning Experience, và kỳ vọng chúng làm con giỏi lên là kỳ vọng đặt nhầm chỗ.</p><h2 id="mot-learning-experience-gom-nhung-gi-​" tabindex="-1">Một Learning Experience gồm những gì <a href="#mot-learning-experience-gom-nhung-gi">​</a> <a class="header-anchor" href="#mot-learning-experience-gom-nhung-gi-​" aria-label="Permalink to &quot;Một Learning Experience gồm những gì [​](#mot-learning-experience-gom-nhung-gi)&quot;">​</a></h2><p>Ở Nemo12, engine phụ trách việc dạy có thể chọn trong tám dạng thành phần, tuỳ vào learner đang ở đâu: Thành phầnDùng khi<strong>Explanation</strong> — giải thíchKhái niệm mới hoàn toàn<strong>Example</strong> — ví dụĐã hiểu nguyên tắc, chưa thấy nó vận hành<strong>Worked Example</strong> — bài mẫu giải sẵnNgười mới, cần thấy trọn vẹn một lời giải đúng<strong>Scaffold</strong> — giàn giáoLàm được một phần, hụt ở một khâu cụ thể<strong>Hint</strong> — gợi ýĐang đi đúng hướng nhưng kẹt<strong>Practice</strong> — luyện tậpĐã hiểu, cần thành thục<strong>Challenge</strong> — thử tháchĐã thành thục, cần đẩy sâu hơn<strong>Reflection</strong> — phản tưCần learner tự nhận ra mình đang nghĩ kiểu gìĐiểm mấu chốt: <strong>thứ tự và liều lượng không cố định</strong>. Cùng một bài &quot;tam giác đồng dạng&quot;, một learner nhận worked example trước rồi mới tới practice; learner khác nhảy thẳng vào challenge vì đã có nền vững. Đây là khác biệt lớn nhất so với một cuốn sách bài tập, vốn buộc mọi đứa trẻ đi qua đúng một con đường.</p><h2 id="đo-kho-đuoc-đieu-chinh-theo-ket-qua-that-​" tabindex="-1">Độ khó được điều chỉnh theo kết quả thật <a href="#đo-kho-đuoc-đieu-chinh-theo-ket-qua-that">​</a> <a class="header-anchor" href="#đo-kho-đuoc-đieu-chinh-theo-ket-qua-that-​" aria-label="Permalink to &quot;Độ khó được điều chỉnh theo kết quả thật [​](#đo-kho-đuoc-đieu-chinh-theo-ket-qua-that)&quot;">​</a></h2><p>Nemo12 điều chỉnh độ khó theo một quy tắc đơn giản, chạy liên tục trong lúc con làm bài: text&gt; 90% đúng → tăng độ khó 65–90% đúng → giữ nguyên, đang ở vùng tốt 40–65% đúng → hạ xuống, thêm scaffold &lt; 40% đúng → dừng lại, kiểm tra kiến thức nềnVùng 65–90% không phải con số tuỳ tiện. Đúng quá nhiều nghĩa là bài đang không dạy được gì; sai quá nhiều nghĩa là learner đang đoán, và đoán thì không tạo ra việc học. Điều Nemo12 <strong>không</strong> làm Khi learner sai nhiều, hệ thống <strong>không</strong> ném thêm 20 bài cùng dạng. Nếu scaffold vẫn không cứu được, đó là tín hiệu kiến thức nền đang thiếu — hệ thống chuyển sang tìm lỗ hổng nền, chứ không tăng khối lượng lên đầu một learner đang đuối. Đây là chỗ khác biệt rõ nhất với luyện đề truyền thống. Khi một học sinh làm sai dạng toán X, phản xạ thông thường là giao thêm bài dạng X. Nếu nguyên nhân thật nằm ở một kỹ năng nền cách đó hai lớp, thì 20 bài kia chỉ tạo ra 20 lần thất bại nữa.</p><h2 id="bon-che-đo-hoc-​" tabindex="-1">Bốn chế độ học <a href="#bon-che-đo-hoc">​</a> <a class="header-anchor" href="#bon-che-đo-hoc-​" aria-label="Permalink to &quot;Bốn chế độ học [​](#bon-che-đo-hoc)&quot;">​</a></h2><p>Tuỳ mức vững hiện tại và độ chắc chắn của kết luận, một Learning Experience chạy ở một trong bốn chế độ:</p><ul><li><strong>Guided</strong> — hệ thống dẫn từng bước, learner xác nhận từng chặng.</li><li><strong>Supported</strong> — learner tự làm, có gợi ý khi kẹt.</li><li><strong>Practice</strong> — learner tự làm, gợi ý chỉ hiện sau khi đã thử.</li><li><strong>Challenge</strong> — bài khó hơn mức hiện tại, chấp nhận learner có thể không làm được. Một learner giỏi vẫn được đưa vào chế độ Guided khi gặp khái niệm hoàn toàn mới. Chế độ gắn với <em>tình huống</em>, không phải với <em>nhãn dán năng lực của đứa trẻ</em>. Nemo12 không có khái niệm &quot;lớp học sinh giỏi&quot; và &quot;lớp học sinh yếu&quot;. Sâu hơn cả chế độ: cùng một phần kiến thức có thể có nhiều Learning Experience khác hẳn nhau — luyện cho thành thục, khám phá từ một bài toán, vá lại nền, hay bài thi đấu. <a href="/decisions/cach-day">Xem hệ thống chọn cách dạy thế nào →</a></li></ul><h2 id="learning-experience-cung-sinh-ra-evidence-​" tabindex="-1">Learning Experience cũng sinh ra Evidence <a href="#learning-experience-cung-sinh-ra-evidence">​</a> <a class="header-anchor" href="#learning-experience-cung-sinh-ra-evidence-​" aria-label="Permalink to &quot;Learning Experience cũng sinh ra Evidence [​](#learning-experience-cung-sinh-ra-evidence)&quot;">​</a></h2><p>Mỗi lần learner làm gì đó trong một Learning Experience — trả lời, dùng gợi ý, mất bao lâu, tự đánh giá mức tự tin — hệ thống ghi lại thành <a href="/learner/evidence">evidence</a>. Nghĩa là việc học và việc hiểu learner diễn ra đồng thời. Nhưng evidence từ Learning Experience có <strong>độ tin cậy thấp hơn</strong> evidence từ một bài đo thật, vì learner được hỗ trợ trong lúc làm. Làm đúng khi có gợi ý là bằng chứng yếu hơn làm đúng một mình. Hệ thống ghi nhận sự khác biệt này thay vì gộp chung — chi tiết ở <a href="/learner/evidence">Evidence</a>. Learning Experience được phép giúp learner. Assessment Experience thì không. Đó là ranh giới giữ cho cả hai đều có nghĩa. <a href="/learning/assessment-experience">Assessment Experience là gì →</a></p>',11)])])}const p=e(g,[["render",c]]);export{s as __pageData,p as default};
